use moloch_live_runtime::{feedback,package_admission};
#[path="../src/quote_priority.rs"]mod quote_priority;
use quote_priority::*;
use baal_transport_service::Scope;
use moloch_replay::session::Session;
use moloch_relationship_arbitrage::{Book,Level,Source,UNIT};
use serde_json::{Value,json};
use std::path::PathBuf;
const NOW:u64=1_792_022_400_000;
const T:&str="11111111-1111-4111-8111-111111111111";
fn iso(n:u64)->String{chrono::DateTime::from_timestamp_millis(n as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn q(ex:&str,side:&str,action:&str,price:i128)->Value{json!({"id":1,"marketId":ex,"exchangeId":ex,"side":side,"action":action,"quantity":10,"filled":0,"price":moloch_replay::money(price),"createdAt":NOW-1000,"activationAt":NOW,"expiresAt":NOW+600000,"retired":false})}
fn book(ex:&str,side:&str,bid:i128,ask:i128)->Book{
 let(bid,ask)=if side=="YES"{(bid,ask)}else{(UNIT-ask,UNIT-bid)};
 let l=|p,n|vec![Level{price:p,quantity:n}];
 Book{exchange_id:ex.into(),source:Source{sha256:"a".repeat(64),received_ms:NOW},observed_ms:NOW,yes_bids:l(bid,25),yes_asks:l(ask,50),no_bids:l(UNIT-ask,50),no_asks:l(UNIT-bid,25)}
}
#[test]fn no_complement_and_distant_cost_floor_are_exact(){let b=book("1048","NO",635000,640000);let quote=q("1048","NO","sell",690000);let original=quote.clone();let d=assess(&quote,Some(&b),NOW,10000).unwrap();assert_eq!(d.class,Class::Deferred);assert_eq!(d.distance_ticks,10);assert_eq!(d.executable_quantity,0);assert_eq!(quote,original);}
#[test]fn fresh_joining_ask_remains_competitive_without_promising_a_fill(){let b=book("1075","NO",895000,900000);let d=assess(&q("1075","NO","sell",900000),Some(&b),NOW,10000).unwrap();assert_eq!(d.class,Class::Competitive);assert_eq!(d.executable_quantity,0);}
#[test]fn visible_marketable_quantity_is_bounded_and_is_not_an_actual_fill(){let mut quote=q("1068","YES","sell",945000);quote["quantity"]=json!(7061);let mut b=book("1068","YES",945000,950000);b.yes_bids[0].quantity=1048;let d=assess(&quote,Some(&b),NOW,10000).unwrap();assert_eq!(d.class,Class::CoveredMarketable);assert_eq!(d.executable_quantity,1048);assert!(d.executable_quantity<quote["quantity"].as_u64().unwrap());}
#[test]fn stale_future_missing_or_incomplete_books_never_prove_a_far_floor(){let quote=q("1","YES","sell",700000);for mode in 0..5{let mut b=book("1","YES",400000,405000);match mode{0=>b.observed_ms=NOW-10001,1=>b.source.received_ms=NOW-10001,2=>b.source.received_ms=NOW+1,3=>b.observed_ms=NOW+1,_=>b.yes_asks.clear()};assert_eq!(assess(&quote,Some(&b),NOW,10000).unwrap().class,Class::NeedsRefresh);}assert_eq!(assess(&quote,None,NOW,10000).unwrap().class,Class::NeedsRefresh);}
#[test]fn freshness_boundary_and_exact_book_scope_are_checked(){let mut b=book("1","YES",400000,405000);b.observed_ms=NOW-10000;b.source.received_ms=NOW-10000;assert_eq!(assess(&q("1","YES","sell",700000),Some(&b),NOW,10000).unwrap().class,Class::Deferred);assert!(assess(&q("2","YES","sell",700000),Some(&b),NOW,10000).is_err());}
#[test]fn only_maximum_age_not_aon_style_claims_risk_priority_without_book(){
 let mut quote=q("1","YES","sell",700000);quote["executionStyle"]=json!("inventoryAON");let old=quote.clone();let b=book("1","YES",400000,405000);
 assert_eq!(assess(&quote,Some(&b),NOW,10000).unwrap().class,Class::Deferred);
 assert_eq!(assess(&quote,None,NOW,10000).unwrap().class,Class::NeedsRefresh);assert_eq!(quote,old);
 quote["inventoryExitReason"]=json!("maximumAge");assert_eq!(assess(&quote,Some(&b),NOW,10000).unwrap().class,Class::RiskExit);assert_eq!(assess(&quote,None,NOW,10000).unwrap().class,Class::RiskExit);
}
#[test]fn profitable_aon_with_real_yes_and_complement_no_depth_is_marketable_not_risk(){
 for side in ["YES","NO"]{let mut quote=q("1",side,"sell",400000);quote["executionStyle"]=json!("inventoryAON");let original=quote.clone();let d=assess(&quote,Some(&book("1",side,400000,405000)),NOW,10000).unwrap();assert_eq!(d.class,Class::CoveredMarketable);assert_eq!(d.executable_quantity,10);assert_eq!(quote,original);}
}
#[test]fn pending_cancellation_retirement_or_expiry_is_never_reordered_into_new_dispatch(){for(field,value)in [("retired",json!(true)),("cancelEffectiveAt",json!(NOW+100)),("expiresAt",json!(NOW))]{let mut quote=q("1","YES","sell",700000);quote["inventoryExitReason"]=json!("maximumAge");quote[field]=value;assert_eq!(assess(&quote,None,NOW,10000).unwrap().class,Class::Inactive);}}
#[test]fn buy_competitiveness_does_not_authorize_crossing_or_reprice_a_quote(){let b=book("1","YES",400000,405000);for(price,class)in [(400000,Class::Competitive),(395000,Class::Deferred),(405000,Class::Deferred)]{let quote=q("1","YES","buy",price);let old=quote.clone();assert_eq!(assess(&quote,Some(&b),NOW,10000).unwrap().class,class);assert_eq!(quote,old);}}
#[test]fn stable_rotation_preserves_fairness_within_priority_classes(){let quotes=vec![q("1","YES","buy",400000),q("2","YES","buy",400000),q("3","YES","buy",400000)];let books=quotes.iter().map(|q|{let ex=q["exchangeId"].as_str().unwrap();(ex.into(),book(ex,"YES",400000,405000))}).collect();let a=rotate(&quotes,&books,NOW,10000,Some("1:YES:buy")).unwrap();assert_eq!(a.ordered_indices,vec![1,2,0]);let b=rotate(&quotes,&books,NOW,10000,Some("3:YES:buy")).unwrap();assert_eq!(b.ordered_indices,vec![0,1,2]);}
#[test]fn risk_and_profitable_covered_depth_precede_entries_and_refresh_without_mutation(){let mut risk=q("risk","YES","sell",700000);risk["inventoryExitReason"]=json!("maximumAge");let quotes=vec![q("stale","YES","buy",400000),q("entry","YES","buy",400000),q("covered","YES","sell",400000),risk,q("far","YES","sell",700000)];let old=quotes.clone();let books=[("entry",400000,405000),("covered",400000,405000),("far",400000,405000)].into_iter().map(|(e,b,a)|(e.into(),book(e,"YES",b,a))).collect();let s=rotate(&quotes,&books,NOW,10000,None).unwrap();assert_eq!(s.ordered_indices,vec![3,2,1,0]);assert_eq!(quotes,old);}
#[test]fn retained_twenty_post_observations_replay_fourteen_far_sells_and_six_competitive_quotes(){
 // Sanitized observations at original POST preflight,22:22:45--22:37:14Z.
 // No actual order/fill IDs, no assigned queue position, no profit inference.
 let rows=[("NO","sell",690000,630000,635000),("YES","sell",300000,245000,250000),("NO","sell",315000,265000,270000),("YES","sell",975000,945000,950000),("NO","sell",835000,815000,820000),("NO","sell",900000,895000,900000),("YES","sell",905000,840000,845000),("NO","sell",180000,165000,170000),("NO","sell",120000,85000,90000),("YES","sell",245000,225000,230000),("YES","buy",185000,185000,190000),("NO","buy",75000,75000,80000),("YES","buy",920000,920000,925000),("YES","buy",265000,265000,270000),("NO","sell",690000,635000,640000),("YES","sell",300000,250000,255000),("NO","sell",315000,265000,270000),("YES","sell",975000,945000,950000),("NO","sell",835000,815000,820000),("NO","sell",900000,895000,900000)];
 let(mut far,mut competitive,mut eligible_buy)=(0,0,0);for(i,(side,action,price,bid,ask))in rows.iter().enumerate(){let ex=(i+1).to_string();let quote=q(&ex,side,action,*price);let d=assess(&quote,Some(&book(&ex,side,*bid,*ask)),NOW,10000).unwrap();match d.class{Class::Deferred=>{assert_eq!(*action,"sell");far+=1;},Class::Competitive=>{competitive+=1;if *action=="buy"{eligible_buy+=1;}},other=>panic!("unexpected {other:?}")}}
 assert_eq!((far,competitive,eligible_buy),(14,6,4));
 // Three far SELL post opportunities occurred after one BUY was generated and
 // before its actual ACK. This is an opportunity count, not wall-clock proof:
 // fresh cached BUY books and mandatory cancel/reconcile work were not frozen.
 let created=chrono::DateTime::parse_from_rfc3339("2026-10-15T22:27:53.386Z").unwrap();let ack=chrono::DateTime::parse_from_rfc3339("2026-10-15T22:32:11.226Z").unwrap();let times=["2026-10-15T22:30:20.142Z","2026-10-15T22:30:42.772Z","2026-10-15T22:31:06.908Z"];
 assert!(times.iter().all(|s|{let t=chrono::DateTime::parse_from_rfc3339(s).unwrap();t>=created&&t<ack}));assert_eq!(ack.signed_duration_since(created).num_milliseconds(),257840);
}
struct Native{root:PathBuf,bank:Session,scope:Scope}
impl Drop for Native{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
impl Native{fn new(transport:Option<&str>)->Self{let root=std::env::temp_dir().join(format!("quote-priority-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));let p=json!({"quantity":5,"maximumMarkets":3,"entryStopAt":iso(NOW+600000)});let seed=json!({"runId":"offline-priority","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(NOW-100000)});let mut bank=Session::open_live(&root,&p,&seed).unwrap();for seq in 1..=2{let received=NOW-100+seq*50;let request=if seq==1{received-10}else{NOW-120000};let mut b=json!({"marketId":"101","exchangeId":"101","tournamentId":T,"sequence":seq.to_string(),"sourceAt":iso(received-1),"requestStartedAt":iso(request),"receivedAt":iso(received),"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]});if let Some(t)=transport{b["transport"]=json!(t);}bank.accept("books",seq,&json!({"type":"book","receivedAt":iso(received),"book":b})).unwrap();}let scope=Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into())].into()};Self{root,bank,scope}}}
#[test]fn actual_native_ws_uses_source_and_receipt_not_initial_request_age(){let f=Native::new(Some("official_sig_realtime"));let quotes=f.bank.engine().order_records();assert!(!quotes.is_empty());let s=from_native(&f.bank,&f.scope,&quotes,NOW,None).unwrap();assert!(s.assessments.iter().any(|a|a.decision.class==Class::Competitive));}
#[test]fn actual_native_rest_retains_request_age_and_gap_does_not_become_far_price_evidence(){let mut f=Native::new(None);let quotes=f.bank.engine().order_records();assert!(!quotes.is_empty());let s=from_native(&f.bank,&f.scope,&quotes,NOW,None).unwrap();assert!(s.assessments.iter().all(|a|a.decision.class==Class::NeedsRefresh));f.bank.accept("gaps",1,&json!({"type":"gap","receivedAt":iso(NOW+1),"exchangeIds":["101"],"reason":"fixture"})).unwrap();let s=from_native(&f.bank,&f.scope,&quotes,NOW+1,None).unwrap();assert!(s.assessments.iter().all(|a|a.decision.class==Class::NeedsRefresh));}
#[test]fn committed_gap_with_previously_fresh_ws_book_requires_refresh(){let mut f=Native::new(Some("official_sig_realtime"));let quotes=f.bank.engine().order_records();assert!(from_native(&f.bank,&f.scope,&quotes,NOW,None).unwrap().assessments.iter().any(|a|a.decision.class==Class::Competitive));f.bank.accept("gaps",1,&json!({"type":"gap","receivedAt":iso(NOW+1),"exchangeIds":["101"],"reason":"fixture"})).unwrap();assert!(from_native(&f.bank,&f.scope,&quotes,NOW+1,None).unwrap().assessments.iter().all(|a|a.decision.class==Class::NeedsRefresh));}
